use std::sync::{Arc, Mutex};

use mlua::{Function, StdLib, prelude::*};
use tracing::{info, warn};

use crate::{
    connections::Update, packets::{Packet, Side, State, UnsureThreshold, s2c::play::Play::SynchronizePlayerPosition}, scripts::{
        OwnType, Script,
        adaptations::{NbtBindings, UpdateBindings},
    },
};

const ENGINE_VERSION: u8 = 1;

const SIDES: usize = 4;
const STATES: usize = 2;

/// Builds the `s2c` / `c2s` namespaces: one table per protocol phase, each
/// holding the constructors generated by `#[derive(LuaPacket)]`.
///
/// The nesting mirrors the Rust enums, so a script writes
/// `s2c.play.ChatMessage { ... }` and gets the opcode from the variant's
/// `#[id(N)]` — never from the packet body, which would be wrong.
fn packet_bindings(lua: &Lua, side: Side) -> LuaResult<LuaTable> {
    let table = lua.create_table()?;
    match side {
        Side::S2C => {
            table.set("handshake", crate::packets::s2c::handshake::Handshake::lua_bindings(lua)?)?;
            table.set("login", crate::packets::s2c::login::Login::lua_bindings(lua)?)?;
            table.set("play", crate::packets::s2c::play::Play::lua_bindings(lua)?)?;
            table.set("status", crate::packets::s2c::status::Status::lua_bindings(lua)?)?;
        }
        Side::C2S => {
            table.set("handshake", crate::packets::c2s::handshake::Handshake::lua_bindings(lua)?)?;
            table.set("login", crate::packets::c2s::login::Login::lua_bindings(lua)?)?;
            table.set("play", crate::packets::c2s::play::Play::lua_bindings(lua)?)?;
            table.set("status", crate::packets::c2s::status::Status::lua_bindings(lua)?)?;
        }
    }
    Ok(table)
}

// Cheap to copy because Lua is Arc + bool
#[derive(Debug, Clone)]
pub struct Engine {
    handlers: Arc<Mutex<[Option<Handler>; 256 * SIDES * STATES]>>, // There is 2 sides and 4 states
    pub(crate) lua: Lua,
    pub(crate) script: Arc<Script>, // because Script is heavy
}

impl Engine {
    pub fn new(script: Arc<Script>) -> LuaResult<Self> {
        let lua = Lua::new_with(
            StdLib::BIT | StdLib::MATH | StdLib::STRING | StdLib::TABLE,
            LuaOptions::default(),
        )?;

        Ok(Self {
            handlers: Arc::new(Mutex::new([const { None }; 256 * 2 * 4])),
            lua,
            script,
        })
    }

    pub fn set_globals(&self) -> LuaResult<()> {
        self.lua.globals().set("engine", self.clone())?;
        self.lua.globals().set("update", UpdateBindings)?;
        self.lua.globals().set("nbt", NbtBindings)?;
        self.lua.globals().set("s2c", packet_bindings(&self.lua, Side::S2C)?)?;
        self.lua.globals().set("c2s", packet_bindings(&self.lua, Side::C2S)?)?;

        self.add_sleep()?;
        self.add_print()?;
        self.add_require()?;

        Ok(())
    }

    pub async fn run(&self, code: &str) -> LuaResult<()> {
        info!("Loading script \"{}\"", self.script.name);
        info!("{}", self.script.description);
        match self.script.engine_version {
            ver if ver < ENGINE_VERSION => return Err(LuaError::external(format!(
                "The engine is outdated: the script is for engine v{}, current version is {}",
                self.script.engine_version, ENGINE_VERSION
            ))),
            ver if ver > ENGINE_VERSION => warn!(
                "The script is outdated: the script is for engine v{}, current version is {}",
                self.script.engine_version, ENGINE_VERSION
            ),
            _ => {}
        };
        self.lua.load(code).exec_async().await
    }

    fn calc_index(packet_id: u8, side: Side, state: State) -> usize {
        let state_id = u8::try_from(state).unwrap() as usize;
        let side_id = u8::try_from(side).unwrap() as usize;
        (side_id * 256) + (state_id * 256 * SIDES) + packet_id as usize
    }

    fn register(&self, state: &str, side: &str, packet_id: u8, own_type: String, func: Function) -> LuaResult<()> {
        let state = State::try_from(state).map_err(|e| LuaError::runtime(e))?;
        let side = Side::try_from(side).map_err(|e| LuaError::runtime(e))?;

        let key = self.lua.create_registry_value(func)?;
        let own_type = OwnType::try_from(own_type.as_str()).map_err(LuaError::external)?;
        
        self.handlers.lock().unwrap()[Self::calc_index(packet_id, side, state)] = Some(Handler { key, own_type });
        Ok(())
    }

    pub async fn on_packet(
        &self,
        side: Side,
        state: State,
        packet_id: u8,
        options: HandlerOptions<'_>,
        own_type: OwnType,
    ) -> LuaResult<Option<Option<Update>>> {
        let func: Function = {
            let handlers = self.handlers.lock().unwrap();
            let Some(ref handler) = handlers[Self::calc_index(packet_id, side, state)] else {
                return Ok(None);
            };
            if handler.own_type != own_type {
                return Ok(None);
            };
            self.lua.registry_value(&handler.key)?
        };
        let result = func.call_async::<Option<Update>>(options).await?;
        Ok(Some(match (result, own_type) {
            // Returning nothing means "leave the packet alone" and is always allowed.
            (None, _) => None,

            // Read-only must not touch the packet in any way.
            (Some(_), OwnType::ReadOnly) => {
                return Err(LuaError::runtime(format!(
                    "handler for packet {packet_id} is registered as \"read\" but returned an Update"
                )));
            }

            // Read-write may replace, but not inject into the other direction.
            (Some(update), OwnType::ReadWrite) if update.inject.is_some() => {
                return Err(LuaError::runtime(format!(
                    "handler for packet {packet_id} is registered as \"read-write\" but returned an inject"
                )));
            }
            (Some(update), OwnType::ReadWrite) => Some(update),

            // Read-inject may inject, but not replace.
            (Some(update), OwnType::ReadInject) if update.change_with.is_some() => {
                return Err(LuaError::runtime(format!(
                    "handler for packet {packet_id} is registered as \"read-inject\" but returned a change_with"
                )));
            }
            (Some(update), OwnType::ReadInject) => Some(update),

            // Full rights: anything goes.
            (Some(update), OwnType::ReadWriteInject) => Some(update),
        }))
    }
}

impl LuaUserData for Engine {
    fn add_methods<M: LuaUserDataMethods<Self>>(methods: &mut M) {
        methods.add_method_mut(
            "register",
            |_lua, this, (state, side, packet_id, own_type, func): (String, String, u8, String, Function)| {
                this.register(&state, &side, packet_id, own_type, func)
            },
        );
    }
}

pub struct HandlerOptions<'a> {
    pub packet: &'a Packet<'a>,
    pub threshold: &'a UnsureThreshold,
    pub is_injected: bool,
}

impl<'a> HandlerOptions<'a> {
    pub fn new(packet: &'a Packet<'a>, threshold: &'a UnsureThreshold, is_injected: bool) -> Self {
        Self { packet, threshold, is_injected }
    }
}

impl IntoLua for HandlerOptions<'_> {
    fn into_lua(self, lua: &Lua) -> LuaResult<LuaValue> {
        let table = lua.create_table()?;
        table.set("packet", self.packet)?;
        table.set("threshold", self.threshold)?;
        table.set("is_injected", self.is_injected)?;
        Ok(LuaValue::Table(table))
    }
}

#[derive(Debug)]
pub struct Handler {
    key: LuaRegistryKey,
    own_type: OwnType,
}